export type ManufacturerAssetCategory =
  | 'racking_detail'
  | 'rail_spec'
  | 'module_spec'
  | 'inverter_spec'
  | 'microinverter_spec'
  | 'optimizer_spec'
  | 'battery_spec';

export interface ManufacturerAsset {
  id: string;
  category: ManufacturerAssetCategory | string;
  equipmentId: string | null;   // joins equipment-db / mounting-hardware-db id
  brand: string;
  model: string;
  assetType: 'pdf' | 'image' | 'svg' | string;
  sourceUrl: string | null;     // verified-resolving manufacturer PDF / download page
  pageRef: string | null;       // page(s) of the key detail/cut sheet within the PDF
  imageUrl: string | null;      // direct image URL if the detail exists standalone
  docTitle: string | null;
  verified: boolean;            // true only when the source_url was fetched + confirmed
  notes: string | null;
}

